        "Очаквани резултати по МОН: Познава основните функционални характеристики на електронните таблици и организацията на работна книга и работни листове. Създава и прилага шаблони (templates) за автоматизирано въвеждане и оформяне на данни. Задава правила за проверка на валидността на въвежданите данни (Data Validation) със списъци, числови интервали и съобщения за грешка. Прилага условно форматиране (Conditional Formatting) чрез правила, цветови скали и ленти с данни за визуален анализ и използва именувани области и функции LOOKUP, HLOOKUP, VLOOKUP.",
