    "originalNoteExcerpt": "Ключови понятия: защита на работен лист (Protect Sheet), защита на работна книга (Protect Workbook), заключени и скрити клетки (Locked / Hidden cells), парола за отваряне и криптиране на файл. Прилага средства за защита на данните в електронна таблица на ниво клетки, работен лист и работна книга. Заключва клетки с формули (Locked/Hidden) и разрешава редактиране само на определени диапазони при защитен лист. Задава парола за отваряне (криптиране) и парола за модифициране на работна книга.",
