    "originalNoteExcerpt": "Ключови понятия: финансови функции (PMT, IPMT, PPMT, FV, PV), условни статистически функции (COUNTIF, SUMIF, AVERAGEIF), анализ със сценарии (What-If Analysis / Scenarios), импортиране на данни от текстов и XML файл. Прилага вградени финансови функции (PMT, IPMT, PPMT, FV, PV) за изчисляване на погасителни вноски по заеми и бъдеща стойност на депозити. Прилага статистически и условни функции (COUNT, COUNTA, COUNTIF, COUNTIFS, SUMIF, SUMIFS, AVERAGEIF, MEDIAN, STDEV) за анализ на извадки. Използва анализ „какво-ако“ със сценарии (What-If Analysis / Scenarios) и зарежда данни от външни източници (текстови файлове, XML, уеб).",
