        "Ключови понятия в темата: база от данни (БД), склад от данни и СУБД, релационен, йерархичен и мрежов модел на данните, таблица, запис (ред) и поле (атрибут), първичен ключ (Primary Key) и външен ключ (Foreign Key), видове връзки между таблици (едно-към-едно, едно-към-много, много-към-много)."
