        "Очаквани резултати по МОН: Описва принципа на действие и основните видове цифрови фотоапарати и видеокамери. Настройва характеристиките на цифровата камера (експозиция, бленда, скорост на затвора, ISO, баланс на бялото, фокус) и прилага композиционни техники и операторски планове при заснемане на открито и закрито. Познава основните файлови формати и стандарти при цифрово фото- и видеозаснемане и осъществява трансфер към компютър.",
