    "originalNoteExcerpt": "Ключови понятия: кадриране и преоразмеряване на растерно изображение, инструменти за селекция (магическа пръчка, ласо, добавяща/изваждаща селекция), ретуширане, клониране (Clone Stamp) и фотографски филтри. Кадрира и преоразмерява растерни изображения с подходяща разделителна способност и пропорции. Използва разнообразни техники за селекция (геометрична, ласо, магнитно ласо, магическа пръчка, добавяща и изваждаща селекция). Прилага корекции на цветовете, ретуширане (клониране, премахване на „червени очи“, замъгляване) и филтри.",
