      "overview": "Кадрира и преоразмерява растерни изображения с подходяща разделителна способност и пропорции. Използва разнообразни техники за селекция (геометрична, ласо, магнитно ласо, магическа пръчка, добавяща и изваждаща селекция). Прилага корекции на цветовете, ретуширане (клониране, премахване на „червени очи“, замъгляване) и филтри. Растерното изображение е мрежа от пиксели с определена разделителна способност (PPI за екран, DPI за печат – стандартно 300 DPI) и цветова дълбочина. Цветовият модел RGB е адитивен (за екрани), а CMYK е субтрактивен (за полиграфически печат). Инструментите за селекция изолират области за локална цветова корекция, преоразмеряване, ретуширане с печат (Clone Stamp) и филтриране.",
