      "overview": "Описва етапите на видеопродукцията, структурата на режисьорския сценарий и ролите в снимачния екип (продуцент, сценарист, режисьор, оператор, осветител, звукооператор, монтажист). Извършва нелинеен видеомонтаж върху видео- и аудиопътечки – подрязване, преходи, наслагване на изображения и титри, синхронизация и подмяна на звук и визуални ефекти. Експортира видеопроекта с подходящ видеокодек и файлов формат и го подготвя за разпространение върху мултимедиен носител или онлайн видео платформи. Създаването на видеоклип преминава през предпродукция (сценарий, режисьорски план, разкадровка), продукция (заснемане на видео и звук) и постпродукция (нелинеен видеомонтаж върху времева линия с видео- и аудиопътечки, преходи, титри, цветокорекция и звуков микс). При експортиране се избира медиа контейнер (MP4, MKV, WebM) и видеокодек (H.264/AVC, H.265/HEVC, AV1) според канала на разпространение.",
