      "overview": "Обяснява необходимостта от тестване на уеб сайт преди и след публикуването му и валидира HTML и CSS кода с инструменти на W3C. Тества уеб сайта с емулатори и браузърни инструменти за съвместимост с различни браузъри, мобилни екрани и изисквания за достъпност. Преди и след публикуване уеб сайтът се подлага на цялостно тестване: 1) Валидиране на HTML и CSS кода с официалните валидатори на W3C (validator.w3.org) за откриване на незатворени тагове и невалидни атрибути; 2) Тестване с емулатори и браузърни DevTools за различни размери на екрана и браузъри; 3) Проверка на хипервръзките и тестване за достъпност (контраст, навигация с клавиатура, четци на екрана).",
