        "Очаквани резултати по МОН: Прилага техники за оптимизация на уеб сайт за търсещи машини (SEO) за подобряване на ранжирането му. Използва инструменти за анализ на посещаемостта и скоростта на сайта, емисии RSS и методики за оценяване на уеб сайт по зададени спецификации.",
        "Практически пример и приложение: Всяка страница от уеб сайта трябва да има уникален таг <title> (до 60 знака) и точно един главен заглавен таг <h1>, съдържащ основните ключови думи за темата на страницата.",
