    "title": "Приложни програми – видове лицензи, инсталиране и поддръжка",
    "originalNoteExcerpt": "Ключови понятия: инсталиране, специфично конфигуриране и поддръжка на приложен софтуер, сравнителен анализ на приложни програми и външна ИКТ поддръжка (Outsourcing). Инсталира, конфигурира и проучва функционалните възможности на приложен софтуер и сравнява програми с едно и също предназначение. Обяснява необходимостта от поддръжка и актуализиране на приложните програми в една организация и преценява кога е необходима външна ИКТ поддръжка.",
