      "overview": "Инсталира, конфигурира и проучва функционалните възможности на приложен софтуер и сравнява програми с едно и също предназначение. Обяснява необходимостта от поддръжка и актуализиране на приложните програми в една организация и преценява кога е необходима външна ИКТ поддръжка. Изборът и управлението на приложни програми в една организация включва сравнителен анализ на функционалните им възможности, проверка на системните изисквания и лицензионния модел, инсталиране, специфично конфигуриране според нуждите на потребителите и редовна поддръжка (обновяване на версиите и пачовете за сигурност). При сложни специфични проблеми организацията прибягва до външни ИКТ специалисти (аутсорсинг).",
